update v2_theme_presets set structure = jsonb_set(structure, '{settings}', (structure->'settings') || '{"theme_flut_style":true,"theme_video_hero":true,"theme_quick_view":true,"theme_size_recommender":true,"theme_live_counter":true,"theme_whatsapp_order":true,"theme_instagram_feed":true,"theme_3d_viewer":true,"theme_countdown_timer":true,"theme_bundle_builder":true,"fabric_stretch":"Orta esneklik — dantel ve elastan karışımı","countdown_label":"Kampanya bitiyor","whatsapp_number":""}'::jsonb) where name = 'Flüt';